package com.shiphappens.logistics.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.time.*; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final Duration expiry; public JwtService(@Value("${app.security.jwt-secret:}") String configuredSecret,@Value("${app.security.jwt-expiration-minutes:60}") long minutes){byte[] bytes;if(configuredSecret==null||configuredSecret.isBlank()){bytes=new byte[64];new SecureRandom().nextBytes(bytes);}else{bytes=configuredSecret.getBytes(StandardCharsets.UTF_8);if(bytes.length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 characters");}key=Keys.hmacShaKeyFor(bytes);expiry=Duration.ofMinutes(minutes);} public String create(String email,String role,Long userId){Instant now=Instant.now();return Jwts.builder().subject(email).claim("role",role).claim("uid",userId).issuedAt(Date.from(now)).expiration(Date.from(now.plus(expiry))).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
